// Package server implements the embedded-SPA HTTP shell (SPEC FR-X serve, N6):
// strict CSP + security headers, SPA fallback to index.html, read-only /files/*.
// No write endpoints, ever.
package server

import (
	"embed"
	"io/fs"
	"net/http"
	"os"
	"path"
	"path/filepath"
	"strings"
)

// Options configures the SPA server.
type Options struct {
	// Dist is the embedded web/dist bundle. Ignored when DevDir is set.
	Dist embed.FS

	// DevDir serves the SPA from disk instead of the embedded bundle
	// (dev-mode flag, PLAN §2 WP3). Enables iteration without rebuild.
	DevDir string

	// FilesDir (optional) mounts [dir] read-only at /files/* (FR-S? / FR-X).
	FilesDir string
}

// CSP for the M0 app: no remote origins, no inline/eval script. Styles and
// images stay restricted to self/data; the app is bundled by vite.
const contentSecurityPolicy = "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; font-src 'self'; object-src 'none'; base-uri 'none'; frame-ancestors 'none'; form-action 'none'"

// New builds the root http.Handler.
func New(opts Options) (http.Handler, error) {
	var assets fs.FS
	if opts.DevDir != "" {
		sub, err := fs.Sub(os.DirFS(opts.DevDir), ".")
		if err != nil {
			return nil, err
		}
		assets = sub
	} else {
		sub, err := fs.Sub(opts.Dist, "dist")
		if err != nil {
			return nil, err
		}
		assets = sub
	}

	mux := http.NewServeMux()

	// Read-only static file mount: /files/* (FR-X). No write endpoints.
	if opts.FilesDir != "" {
		filesDir := http.Dir(filepath.Clean(opts.FilesDir))
		mux.Handle("GET /files/", guardTraversal(http.StripPrefix("/files/", serveReadOnly(filesDir))))
	}

	mux.Handle("GET /", spaHandler(assets))

	return securityHeaders(mux), nil
}

// serveReadOnly: no directory listings, no writes (http.FileServer with dir
// listing disabled via a no-op on directories).
func serveReadOnly(dir http.Dir) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		upath := path.Clean("/" + r.URL.Path)
		if upath == "/" || strings.HasSuffix(upath, "/") {
			http.Error(w, "directory listing disabled", http.StatusForbidden)
			return
		}
		http.FileServer(dir).ServeHTTP(w, r)
	})
}

// guardTraversal rejects paths escaping FilesDir (N6: path traversal guarded).
func guardTraversal(next http.Handler) http.Handler {
	return http.HandlerFunc(func w-handler) }
