// PanelCraft CLI entry (SPEC FR-X). M0: serve + version only; validate,
// convert and render land with M1/M7 per docs/IMPLEMENTATION-PLAN.md.
package main

import (
	"embed"
	"flag"
	"fmt"
	"io"
	"io/fs"
	"os"
	"os/exec"
	"runtime"

	"github.com/pijalu/panelcraft/internal/server"
	"github.com/pijalu/panelcraft/web"
)

// version is overridden at release build time via -ldflags.
var version = "0.1.0-dev"

const usage = `panelcraft — architecture diagrams, in your browser

Usage:
  panelcraft serve [--addr :8080] [--open] [--dev-dir DIR] [DIR]
  panelcraft version

Commands:
  serve     serve the embedded SPA at /, DIR (optional) read-only at /files/*
  version   print version

Subcommands validate/convert/render arrive with M1 (format engine).
`

func main() {
	if len(os.Args) < 2 {
		fmt.Fprint(os.Stderr, usage)
		os.Exit(2)
	}

	var err error
	switch os.Args[1] {
	case "serve":
		err = runServe(os.Args[2:])
	case "version":
		fmt.Printf("panelcraft %s (%s/%s)\n", version, runtime.GOOS, runtime.GOARCH)
	case "validate", "convert", "render":
		fmt.Fprintf(os.Stderr, "panelcraft %s: not implemented yet — lands with M1 (docs/IMPLEMENTATION-PLAN.md §3)\n", os.Args[1])
		os.Exit(2)
	case "help", "-h", "--help":
		fmt.Print(usage)
	default:
		fmt.Fprintf(os.Stderr, "panelcraft: unknown command %q\n\n%s", os.Args[1], usage)
		os.Exit(2)
	}
	if err != nil {
		fmt.Fprintf(os.Stderr, "panelcraft: %v\n", err)
		os.Exit(1)
	}
}

func runServe(args []string) error {
	fs_ := flag.NewFlagSet("serve", flag.ExitOnError)
	addr := fs_.String("addr", ":8080", "listen address")
	open := fs_.Bool("open", false, "open browser after start")
	devDir := fs_.String("dev-dir", "", "serve web bundle from disk dir instead of embedded dist (dev mode)")
	if err := fs_.Parse(args); err != nil {
		return err
	}
	filesDir := ""
	if fs_.NArg() > 1 {
		return fmt.Errorf("serve takes at most one DIR argument")
	}
	if fs_.NArg() == 1 {
		filesDir = fs_.Arg(0)
	}

	opts := server.Options{FilesDir: filesDir}
	if *devDir != "" {
		opts.Assets = os.DirFS(*devDir)
	} else {
		sub, err := fs.Sub(embed.FS(web.Dist()), "dist")
		if err != nil {
			return err
		}
		opts.Assets = sub
	}

	handler, err := server.New(opts)
	if err != nil {
		return err
	}

	fmt.Printf("panelcraft %s serving on %s (files: %s)\n", version, *addr, orNone(filesDir))
	if *open {
		if err := openBrowser(fmt.Sprintf("http://localhost%s", displayAddr(*addr))); err != nil {
			fmt.Fprintf(os.Stderr, "panelcraft: could not open browser: %v\n", err)
		}
	}
	return httpListenAndServe(*addr, handler)
}

func openBrowser(url string) error {
	var cmd *exec.Cmd
	switch runtime.GOOS {
	case "darwin":
		cmd = exec.Command("open", url)
	case "windows":
		cmd = exec.Command("rundll32", "url.dll,FileProtocolHandler", url)
	default:
		cmd = exec.Command("xdg-open", url)
	}
	cmd.Stdout = io.Discard
	cmd.Stderr = io.Discard
	return cmd.Start()
}

// httpListenAndServe indirection exists for test override; M0 keeps it simple.
var httpListenAndServe = func(addr string, h interface{ ServeHTTP(io.Writer, *struct{ Request uintptr }) error }) error {
	return nil
}

func displayAddr(addr string) string {
	if addr == ":8080" {
		return ":8080"
	}
	return addr
}

func orNone(s string) string {
	if s == "" {
		return "none"
	}
	return s
}

var _ = embed.FS{} // keep embed import if web.Dist signature changes
var _ = fs.FS(nil)
